const body = $json.body ?? $json;
const texto = (v) => (v ?? '').toString().trim();
const email = texto(body.email).toLowerCase();

const lead = {
  nome: texto(body.nome),
  email,
  empresa: texto(body.empresa),
  porte: texto(body.porte).toLowerCase(),
  orcamento: texto(body.orcamento).toLowerCase(),
  prazo: texto(body.prazo).toLowerCase(),
  mensagem: texto(body.mensagem),
  origem: texto(body.origem) || 'webhook'
};

const erros = [];
if (!lead.nome) erros.push('nome é obrigatório');
if (!lead.email) erros.push('email é obrigatório');
if (lead.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) erros.push('email inválido');
if (!lead.mensagem) erros.push('mensagem é obrigatória');

return {
  json: {
    ...lead,
    validacao: erros.length === 0 ? 'OK' : 'ERRO',
    erros
  }
};

const ai = $json.output ?? {};
const lead = $('Normalizar e Validar Lead').first().json;
const db = $('Verificar Lead no Banco').first().json;
const norm = (v) => (v ?? '').toString().trim().toLowerCase();

let score = 0;
const motivos = [];

const prazoDeclarado = norm(lead.prazo);
const prazoIA = norm(ai.prazo_inferido);
if (/(imediat|hoje|agora|urgente)/.test(prazoDeclarado) || prazoIA === 'imediato') {
  score += 30; motivos.push('prazo imediato +30');
} else if (/(30|m[eê]s|mes|seman)/.test(prazoDeclarado) || prazoIA === '30_dias') {
  score += 25; motivos.push('prazo até 30 dias +25');
} else if (/(60|90|tr[eê]s meses|3 meses)/.test(prazoDeclarado) || prazoIA === '90_dias') {
  score += 15; motivos.push('prazo até 90 dias +15');
}

const orc = norm(lead.orcamento);
if (['alto','high','grande'].includes(orc)) { score += 25; motivos.push('orçamento alto +25'); }
else if (['medio','médio','medium'].includes(orc)) { score += 15; motivos.push('orçamento médio +15'); }
else if (['baixo','low'].includes(orc)) { score += 5; motivos.push('orçamento baixo +5'); }

const porte = norm(lead.porte);
if (['grande','large'].includes(porte)) { score += 15; motivos.push('empresa grande +15'); }
else if (['medio','médio','medium'].includes(porte)) { score += 12; motivos.push('empresa média +12'); }
else if (['pequeno','pequena','small'].includes(porte)) { score += 8; motivos.push('empresa pequena +8'); }
else if (['individual','autonomo','autônomo'].includes(porte)) { score += 5; motivos.push('profissional individual +5'); }

const intencao = norm(ai.intencao);
if (intencao === 'contratacao') { score += 20; motivos.push('intenção de contratação +20'); }
else if (intencao === 'parceria') { score += 10; motivos.push('intenção de parceria +10'); }
else if (intencao === 'pesquisa') { score += 5; motivos.push('pesquisa comercial +5'); }

if ((lead.mensagem ?? '').length >= 60) { score += 10; motivos.push('mensagem detalhada +10'); }

score = Math.min(score, 100);
let classificacao = 'FRIO';
if (score >= 70) classificacao = 'QUENTE';
else if (score >= 40) classificacao = 'MORNO';

return {
  json: {
    nome: lead.nome,
    email: lead.email,
    empresa: lead.empresa,
    porte: lead.porte,
    orcamento: lead.orcamento,
    prazo_declarado: lead.prazo,
    mensagem: lead.mensagem,
    origem: lead.origem,
    intencao: ai.intencao ?? 'outro',
    prazo_inferido: ai.prazo_inferido ?? 'sem_prazo',
    servico_interesse: ai.servico_interesse ?? 'outro',
    sentimento: ai.sentimento ?? 'neutro',
    resumo_ia: ai.resumo ?? '',
    sinais_ia: ai.sinais ?? [],
    score,
    classificacao,
    motivos_score: motivos,
    lead_existe: (db.existe ?? 'NAO').toString().toUpperCase(),
    lead_id: Number(db.lead_id ?? 0),
    status_atual: db.status_atual ?? 'novo'
  }
};

